import uuid

from django.db import migrations

from vitrina.datasets.helpers import generate_unique_dataset_name
from vitrina.structure import VersionStatus


def create_metadata_rows_for_datasets(apps, schema_editor):
    Dataset = apps.get_model("vitrina_datasets", "Dataset")
    ContentType = apps.get_model("contenttypes", "ContentType")
    Metadata = apps.get_model("vitrina_structure", "Metadata")
    Version = apps.get_model("vitrina_structure", "Version")
    dataset_content_type = ContentType.objects.get_for_model(Dataset)

    for dataset in Dataset.objects.all():
        draft_metadata_version = Version.objects.filter(dataset=dataset, status=VersionStatus.DRAFT).order_by("-version").first()
        if not Metadata.objects.filter(dataset=dataset, content_type=dataset_content_type).exists():
            dataset_name = generate_unique_dataset_name(dataset.organization, dataset)
            Metadata.objects.create(
                uuid=str(uuid.uuid4()),
                dataset=dataset,
                content_type=dataset_content_type,
                object_id=dataset.pk,
                name=dataset_name,
                title=dataset.title,
                description=dataset.description,
                prepare_ast={},
                version=1,
                metadata_version=draft_metadata_version,
            )


def fix_dataset_distributions(apps, schema_editor):
    Dataset = apps.get_model("vitrina_datasets", "Dataset")
    DatasetDistribution = apps.get_model("vitrina_resources", "DatasetDistribution")
    ContentType = apps.get_model("contenttypes", "ContentType")
    Metadata = apps.get_model("vitrina_structure", "Metadata")

    dd_ct = ContentType.objects.get_for_model(DatasetDistribution)

    for dataset in Dataset.objects.all():
        dataset_models = dataset.model_set.select_related("distribution__format")
        for model in dataset_models.all():
            dist = model.distribution
            if not dist:
                continue
            if dist.format.extension != "UAPI":
                continue

            if getattr(dist, "metadata_version_id", None):
                dist.metadata_version = None
                dist.save(update_fields=["metadata_version"])

            Metadata.objects.filter(content_type=dd_ct, object_id=dist.pk).delete()

            model.distribution = None
            model.save(update_fields=["distribution"])


def create_metadata_rows_for_dataset_distribution(apps, schema_editor):
    DatasetDistribution = apps.get_model("vitrina_resources", "DatasetDistribution")
    ContentType = apps.get_model("contenttypes", "ContentType")
    Metadata = apps.get_model("vitrina_structure", "Metadata")
    dataset_distribution_content_type = ContentType.objects.get_for_model(DatasetDistribution)

    for dataset_distribution in DatasetDistribution.objects.all():
        if not Metadata.objects.filter(dataset=dataset_distribution.dataset, content_type=dataset_distribution_content_type).exists():
            name = (
                Metadata.objects.filter(
                    dataset=dataset_distribution.dataset,
                    content_type=ContentType.objects.get_for_model(DatasetDistribution),
                    name__iregex=r"resource[0-9]+",
                )
                .order_by("name")
                .values_list("name", flat=True)
                .last()
            )
            if not name:
                name = "resource1"
            else:
                n = name.replace("resource", "")
                try:
                    n = int(n)
                except ValueError:
                    n = 0
                n += 1
                name = f"resource{n}"

            Metadata.objects.create(
            uuid=str(uuid.uuid4()),
            dataset=dataset_distribution.dataset,
            content_type=dataset_distribution_content_type,
            object_id=dataset_distribution.pk,
            name=name,
            prepare_ast={},
            access=None,
            version=1,
            # metadata_version=dataset_distribution.metadata_version,
        )


